type ClaimFinding = unverifiedClaimFinding

type ClaimsPageScan struct {
	PageID   string
	PageName string
	Findings []unverifiedClaimFinding
	ComponentsExamined int
	ComponentsSkippedLocked int
}

func ScanDeployedClaims(ctx context.Context, db *sql.DB, siteID uuid.UUID, pageIDFilter string, eb *datahelpers.EvidenceBase, rowExists bool, logger *zap.Logger) ([]*ClaimsPageScan, []unverifiedClaimFinding, error) {
	pageQuery := `
		SELECT pc.page_id::text, p.name, COALESCE(pc.slot_name, ''),
		       COALESCE(pc.rendered_html, ''), COALESCE(cc.name, ''),
		       COALESCE(pc.content_data::text, ''), COALESCE(p.page_type, ''),
		       pc.locked_at
		FROM page_components pc
		JOIN pages p ON p.id = pc.page_id
		LEFT JOIN content_components cc ON cc.id = pc.component_id
		WHERE p.site_id = $1
		  AND ( (pc.rendered_html IS NOT NULL AND pc.rendered_html <> '')
		     OR (pc.content_data IS NOT NULL AND pc.content_data::text <> '{}') )`
	if strings.TrimSpace(pageIDFilter) != "" {
		pageQuery += ` AND pc.page_id = $2::uuid`
		pageArgs = append(pageArgs, strings.TrimSpace(pageIDFilter))
	}
	...
	if lockedAt.Valid {
		pf.ComponentsSkippedLocked++
		continue
	}
	pf.ComponentsExamined++
	// scans unchanged, appended to pf.Findings
	return pageOrder, siteFindings, nil
}

// NOTE: no p.status filter — this check has never had one, and the
// revalidator must judge by the emit side's exact predicate.

// emit side, same file:
eb, rowExists, err := LoadEvidenceBase(dctx.Ctx, dctx.DB, dctx.SiteID)
scans, siteFindings, err := ScanDeployedClaims(dctx.Ctx, dctx.DB, dctx.SiteID, "", eb, rowExists, dctx.Logger)
for _, pf := range scans {
	if len(pf.Findings) == 0 { continue }   // emitted output unchanged
	pageFindings = append(pageFindings, pf)
}

// SIGNATURE NOTE, so this does not read as disagreeing with edits 4/6: the form below is
// this edit's own shape, BEFORE edit 6 adds the two gates. The shipped signature, after
// edits 6 and 7, is:
//   unverifiedClaimsVerdict(pageID string, filedAt time.Time, flagged []flaggedClaim, scan *checks.ClaimsPageScan)
// filedAt comes from edit 8 (parkedReviewItem.CreatedAt); flagged from the item's own spec.findings[].
func unverifiedClaimsVerdict(pageID string, scan *checks.ClaimsPageScan) revalidationVerdict {
	if scan == nil { return unknown("an unbuilt page is not evidence the claims were removed") }
	if scan.ComponentsExamined == 0 { return unknown("every rendered component on this page is human-locked ... the audit examined nothing") }
	if len(scan.Findings) > 0 { return stillHolds("page %s still carries %d claim(s) the register does not support") }
	if scan.ComponentsSkippedLocked > 0 { return unknown("... human-locked component(s) were not read, and the reported claims may sit in those") }
	return resolved("re-scanned all %d component(s) ... found no unsupported claim")
}

// and, before the scan:
if !rowExists {
	return unknown("site has no current evidence_base spec ... withdrawing the register is not evidence the claims were substantiated")
}

// ONE signature throughout, matching the shipped code after edit 6:
//   unverifiedClaimsVerdict(pageID string, filedAt time.Time, flagged []flaggedClaim, scan *checks.ClaimsPageScan)
var flaggedHero = []flaggedClaim{{Check: "unregistered_number", Slot: "hero", Matched: "90,790"}}
func heroCleaned() map[string]string   { return map[string]string{"hero": "<p>We help small firms adopt AI.</p>"} }
func heroUntouched() map[string]string { return map[string]string{"hero": "<p>Trusted by 90,790 customers.</p>"} }

unreadable := []*checks.ClaimsPageScan{nil, {PageID: "p1"}, {PageID: "p1", ComponentsSkippedLocked: 1}, {PageID: "p1", ComponentsSkippedLocked: 9}}
for _, scan := range unreadable {
	if unverifiedClaimsVerdict("p1", filedAt, flaggedHero, scan).Verdict == revalidationResolved {
		t.Errorf("produced `resolved` without examining a component")
	}
}

// THE CLAIM-GRANULAR PROPERTY. changedAfter is passed on purpose: the owner's
// timestamp gate is SATISFIED here, so only the new gate can refuse. If this ever
// passes because the timestamp refused, it asserts nothing.
got := unverifiedClaimsVerdict("p1", filedAt, flaggedHero, &checks.ClaimsPageScan{
	PageID: "p1", PageName: "about", ComponentsExamined: 3,
	NewestComponentUpdate: changedAfter, ExaminedTextBySlot: heroUntouched(),
})
if got.Verdict == revalidationResolved {
	t.Fatalf("closed a factual-claim item while the text it cited (%q) is still in its slot", flaggedHero[0].Matched)
}

// TestUnverifiedClaimsNeverResolvesWhenOnlyTheRegisterMoved — the gate's four failure modes.
// NOTE the signature: filedAt is the SECOND parameter, supplied by edit 8's parkedReviewItem.CreatedAt;
// `flagged` is the THIRD, and heroCleaned() is passed so these cases reach the timestamp gate
// rather than refusing at the claim gate and passing for the wrong reason.
cases := []struct {
	name    string
	newest  time.Time
	filedAt time.Time
}{
	{"component edited before the finding was filed", changedBefore, filedAt},
	{"component edited at exactly the filing instant", filedAt, filedAt},
	{"no timestamp at all on any examined component", time.Time{}, filedAt},
	{"filing date unknown, page edited long ago", changedBefore, time.Time{}},
}
for _, tc := range cases {
	t.Run(tc.name, func(t *testing.T) {
		got := unverifiedClaimsVerdict("p1", tc.filedAt, flaggedHero, &checks.ClaimsPageScan{
			PageID: "p1", PageName: "about", ComponentsExamined: 3,
			NewestComponentUpdate: tc.newest, ExaminedTextBySlot: heroCleaned(),
		})
		if got.Verdict == revalidationResolved {
			t.Errorf("a clean page whose copy cannot be shown to have moved returned `resolved`")
		}
	})
}

// ROUND 6, the claim-granular gate, ahead of the owner's timestamp gate:
var stillPresent, unjudgeable []string
for _, c := range flagged {
	present, judgeable := claimStillOnPage(scan, c)
	switch {
	case !judgeable:
		unjudgeable = append(unjudgeable, fmt.Sprintf("%s:%s", c.Check, c.Slot))
	case present:
		stillPresent = append(stillPresent, fmt.Sprintf("%s:%s", c.Check, c.Slot))
	}
}
if len(stillPresent) > 0 {
	return stillHolds("page %s no longer trips the check, but %d of the %d text(s) this finding cited are STILL in the component they were cited from - so the standard moved, not the copy")
}
if len(unjudgeable) > 0 {
	return unknown("... the slot they were cited from was not among the components examined (deleted, renamed or human-locked), and an absent component is not evidence the claim was removed")
}

// the token, NOT the snippet - 40/41 vs 18/41 on the demand control:
func claimStillOnPage(scan *checks.ClaimsPageScan, c flaggedClaim) (present, judgeable bool) {
	if strings.TrimSpace(c.Matched) == "" {
		return false, false
	}
	text, ok := scan.ExaminedTextBySlot[c.Slot]
	if !ok {
		return false, false   // could not look != it is gone
	}
	return strings.Contains(strings.ToLower(text), strings.ToLower(c.Matched)), true
}

// and the owner's gate, unchanged, still ANDed after it:
if filedAt.IsZero() {
	return unknown("this finding carries no filing date, so there is nothing to compare the page's last edit against")
}
if !scan.NewestComponentUpdate.After(filedAt) {
	return unknown("page %s no longer trips the check, but no component on it has changed since this finding was filed — so the site's evidence register moved, not the page; a register entry proves a claim was registered, never that it is true")
}
return resolved(...)  // evidence carries BOTH item_filed_at and newest_component_update
